import { createReadStream, createWriteStream } from 'node:fs';
import { readFile } from 'node:fs/promises';
import { EventEmitter } from 'node:events';
import { Readable, Transform } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import readline from 'node:readline';

class PemantauLog extends EventEmitter {
  async baca(file) {
    const status = {};
    const rl = readline.createInterface({ input: createReadStream(file) });
    for await (const baris of rl) {
      const [waktu, metode, jalur, kode] = baris.split(' ');
      status[kode] = (status[kode] || 0) + 1;
      if (kode.startsWith('5')) this.emit('peringatan', `${waktu} ${metode} ${jalur}`);
    }
    return status;
  }
}
const pemantau = new PemantauLog();
pemantau.on('peringatan', (info) => console.log('PERINGATAN:', info));
const status = await pemantau.baca('akses.log');

const keBaris = new Transform({
  objectMode: true,
  transform([kode, n], enc, cb) { cb(null, `${kode}: ${n}\n`); },
});
await pipeline(Readable.from(Object.entries(status)), keBaris, createWriteStream('laporan.txt'));
console.log((await readFile('laporan.txt', 'utf8')).trim().split('\n').join(' | '));

