import { createReadStream } from 'node:fs';
import { EventEmitter } from 'node:events';
import readline from 'node:readline';
const sensor = new EventEmitter();
sensor.on('panas', (nama) => console.log(`Panas: ${nama}`));
const rl = readline.createInterface({ input: createReadStream('suhu.log') });
for await (const baris of rl) {
  const [nama, suhu] = baris.split(' ');
  if (Number(suhu) > 30) sensor.emit('panas', nama);
}
